um ditimbang' : number_format($item->actual_milli / 1000, 3, ',', '.').' '.($item->tariff_snapshot['unit'] === 'kg' ? 'kg' : 'potong') }}<br>{{ $item->actual_amount === null ? '—' : 'Rp '.number_format($item->actual_amount, 0, ',', '.') }}</td></tr>@endforeach</tbody></table><section><p>Estimasi jasa: <strong>{{ $order->estimated_total === null ? 'Belum lengkap' : 'Rp '.number_format($order->estimated_total, 0, ',', '.') }}</strong></p><p>Nilai jasa hasil timbang: <strong>{{ $order->actual_total === null ? 'Belum tersedia' : 'Rp '.number_format($order->actual_total, 0, ',', '.') }}</strong></p><p>Minimum dan pembulatan berlaku per kantong. Nilai ini hanya untuk jasa laundry. Bukti penerimaan ini belum menyatakan pembayaran diterima.</p>@if($order->approved_at)<p>Nilai jasa disetujui {{ $order->approved_name }} · {{ $order->approved_at->format('d M Y H:i') }} WIB.</p>@endif @if($order->status === 'cancelled')<p><strong>PENERIMAAN DIBATALKAN</strong> · {{ $order->cancellation_reason }}</p>@endif</section><section><h3>Instruksi pelanggan</h3><p class="laundry-preserve">{{ $order->instructions ?: 'Tidak ada instruksi khusus.' }}</p><h3>Ketentuan saat penerimaan</h3><p class="laundry-preserve">{{ $order->outlet_snapshot['terms'] ?: 'Ketentuan dikonfirmasi bersama admin outlet.' }}</p></section>@include('admin.laundry.orders.handover-proof')</main><script src="{{ asset('js/laundry.js') }}" defer></script></body></html>
